WITH base AS (SELECT * FROM accounts WHERE opened_date BETWEEN '2023-04-16' AND '2025-03-01'), AccountsStats AS (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, YEAR(opened_date) AS opened_year, ROUND((100 * SUM(CASE WHEN account_type = 'SAVINGS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_savings, AVG(balance) AS avg_balance FROM base GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END, YEAR(opened_date)) SELECT opened_cohort, opened_year, pct_savings, avg_balance FROM AccountsStats ORDER BY avg_balance DESC;
